const descripcion = items[0].json.descripcion.toLowerCase();
const categorias = {
  'alquiler': ['alquiler', 'renta', 'casa'],
  'comida': ['comida', 'almuerzo', 'cena', 'café', 'restaurante'],
  'transporte': ['transporte', 'taxi', 'uber', 'bus'],
  'entretenimiento': ['cine', 'película', 'concierto', 'diversión'],
  'servicios': ['luz', 'agua', 'internet', 'teléfono'],
  'salud': ['doctor', 'medicina', 'farmacia', 'hospital'],
  'educacion': ['curso', 'libro', 'clase'],
  'compras': ['compra', 'tienda', 'mercado']
};

let categoria = 'otro';
for (const [cat, keywords] of Object.entries(categorias)) {
  if (keywords.some(k => descripcion.includes(k))) {
    categoria = cat;
    break;
  }
}

return { categoria, confianza: 0.85 };

const gastos = items[0].json.gastos;
const totalesPorCategoria = {};
let totalMes = 0;

gastos.forEach(gasto => {
  const cat = gasto.categoria || 'sin categoría';
  totalesPorCategoria[cat] = (totalesPorCategoria[cat] || 0) + parseFloat(gasto.monto);
  totalMes += parseFloat(gasto.monto);
});

let resumen = `Resumen del mes\n\nTotal gastado: $${totalMes}\nCantidad de gastos: ${gastos.length}\n\nDesglose por categoría:\n`;

Object.entries(totalesPorCategoria).forEach(([cat, monto]) => {
  const porcentaje = ((monto / totalMes) * 100).toFixed(1);
  resumen += `• ${cat}: $${monto} (${porcentaje}%)\n`;
});

return { resumen, totalMes, cantidadGastos: gastos.length, detallesPorCategoria: totalesPorCategoria };
